package app.rwun;
import java.time.*;import java.util.*;import org.json.*;
/** Walking history is deliberately separate from running mileage and running adaptation. */
final class WalkData {
 static void validate(JSONArray walks)throws Exception{if(walks.length()>5000)throw new IllegalArgumentException("Archive walking history before adding more");Set<String> ids=new HashSet<>();for(int i=0;i<walks.length();i++){JSONObject r=walks.getJSONObject(i);String id=r.getString("id");if(!id.startsWith("walk:")||id.length()>180||!ids.add(id))throw new IllegalArgumentException("Invalid walk identity");LocalDate.parse(r.getString("date"));V103Data.whole(r,"seconds",1,180000);double km=r.getDouble("km");if(!Double.isFinite(km)||km<0||km>250)throw new IllegalArgumentException("Invalid walking distance");String route=r.optString("route");if(!route.isEmpty()&&!route.matches("route-[a-zA-Z0-9-]+\\.jsonl"))throw new IllegalArgumentException("Invalid walking route");V103Data.whole(r,"hr",0,249);V103Data.whole(r,"rpe",0,10);V103Data.whole(r,"fatigue",1,5);if(!(r.get("pain") instanceof Boolean)||r.getString("source").length()>180)throw new IllegalArgumentException("Invalid walking feedback");}}
 static JSONObject from(RunStore.Run r)throws Exception{return new JSONObject().put("id",r.sessionId()).put("date",r.date()).put("km",r.km()).put("seconds",r.seconds()).put("source",r.source()).put("distanceKnown",r.km()>0).put("route",r.routeFile()).put("hr",r.avgHr()).put("rpe",r.rpe()).put("fatigue",r.fatigue()).put("pain",r.pain());}
 static JSONArray outdoor(JSONObject data){JSONArray rows=data.optJSONArray("walks");return rows==null?new JSONArray():rows;}
 static List<JSONObject> all(JSONObject data){List<JSONObject> list=new ArrayList<>();JSONArray outdoor=outdoor(data);for(int i=0;i<outdoor.length();i++)list.add(outdoor.optJSONObject(i));JSONArray indoor=data.optJSONArray("indoor");if(indoor!=null)for(int i=0;i<indoor.length();i++){JSONObject r=indoor.optJSONObject(i);if(r!=null&&r.optString("kind").equals("Walk"))list.add(r);}list.sort(Comparator.comparing(r->r.optString("date")));return List.copyOf(list);}
 record Week(long seconds,double km,int sessions,int days){}
 static Week week(JSONObject data,LocalDate today){long seconds=0;double km=0;int sessions=0;Set<String> days=new HashSet<>();for(JSONObject r:all(data)){LocalDate date=LocalDate.parse(r.optString("date"));if(date.isBefore(today.minusDays(6))||date.isAfter(today))continue;seconds+=r.optLong("seconds");km+=r.optDouble("km",0);sessions++;days.add(date.toString());}return new Week(seconds,km,sessions,days.size());}
}
